<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class MinorMedicationPlan extends Model { protected $fillable=['facility_id','minor_id','medication_id','dose_quantity','dosage_unit_id','administration_route_id','prescriber_staff_member_id','prescription_minor_document_id','start_date','end_date','instructions','is_active','created_by_user_id','updated_by_user_id']; protected function casts():array{return ['dose_quantity'=>'decimal:3','start_date'=>'date','end_date'=>'date','instructions'=>'encrypted','is_active'=>'boolean'];} public function minor():BelongsTo{return $this->belongsTo(Minor::class);} public function medication():BelongsTo{return $this->belongsTo(Medication::class);} public function dosageUnit():BelongsTo{return $this->belongsTo(MedicationDosageUnit::class);} public function administrationRoute():BelongsTo{return $this->belongsTo(MedicationAdministrationRoute::class);} public function prescriber():BelongsTo{return $this->belongsTo(StaffMember::class,'prescriber_staff_member_id');} public function prescriptionDocument():BelongsTo{return $this->belongsTo(MinorDocument::class,'prescription_minor_document_id');} public function schedules():HasMany{return $this->hasMany(MinorMedicationSchedule::class);} public function administrations():HasMany{return $this->hasMany(MinorMedicationAdministration::class);} }
